import { readFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it, vi } from 'vitest'
import { GcodeParser, MOVE_EXTRUDE, MOVE_FEED, MOVE_RAPID, parseGcode, type ParsedGcode } from './parse'
import { FileTooBig, isGcodeFileUrl, runParse, transferables } from './run'

/** Move i as [x0, y0, z0, x1, y1, z1] */
const seg = (p: ParsedGcode, i: number) => [...p.segments.subarray(i * 6, i * 6 + 6)]
const ends = (p: ParsedGcode, i: number) => seg(p, i).slice(3)

const ORCA = [
  '; generated by OrcaSlicer 2.4.2 on 2026-09-29',
  'G90',
  'M83',
  'G92 E0',
  'G1 X10 Y10 F9000',
  ';LAYER_CHANGE',
  ';Z:0.2',
  'G1 Z0.2 F600',
  'G1 X20 Y10 E0.5 F1800',
  'G1 X20 Y20 E0.5',
  'G1 E-0.8 F2400',
  'G1 Z0.6',
  'G1 X40 Y40 F9000',
  'G1 Z0.2',
  'G1 E0.8',
  'G1 X50 Y40 E0.4',
  ';LAYER_CHANGE',
  ';Z:0.4',
  'G1 Z0.4',
  'G1 X60 Y40 E0.5',
].join('\n')

describe('moves', () => {
  it('reads a slicer file into moves, and retracts add no line', () => {
    const p = parseGcode(ORCA)
    expect(p.hasExtrusion).toBe(true)
    // The first travel and the first Z have nothing to draw from; the two E-only lines add nothing
    expect(p.moveCount).toBe(8)
    expect(seg(p, 0).map((v) => +v.toFixed(3))).toEqual([10, 10, 0.2, 20, 10, 0.2])
    expect(p.kinds[0]).toBe(MOVE_EXTRUDE)
    expect(p.kinds[3]).toBe(MOVE_FEED)
    expect(ends(p, 3).map((v) => +v.toFixed(3))).toEqual([40, 40, 0.6])
  })

  it('has nothing to draw from until X and Y are known', () => {
    const p = parseGcode('G1 X5\nG1 Y5\nG1 X6')
    expect(p.moveCount).toBe(1)
    expect(seg(p, 0)).toEqual([5, 5, 0, 6, 5, 0])
  })

  it('G0 is rapid; G0 with extrusion counts as extruding, as in Klipper', () => {
    const p = parseGcode('G0 X0 Y0\nG0 X5\nG0 X9 E1')
    expect(p.kinds[0]).toBe(MOVE_RAPID)
    expect(p.kinds[1]).toBe(MOVE_EXTRUDE)
  })

  it('absolute E counts the change, and G92 resets it', () => {
    const p = parseGcode('G0 X0 Y0\nM82\nG1 X1 E5\nG1 X2 E5\nG92 E0\nG1 X3 E0.4\nG1 X4 E0.1')
    expect([...p.kinds]).toEqual([MOVE_EXTRUDE, MOVE_FEED, MOVE_EXTRUDE, MOVE_FEED])
  })

  it('G91 makes moves and E relative, like Klipper', () => {
    const p = parseGcode('G90\nG0 X10 Y10 Z1\nG91\nG1 X5 Y-5 E1\nG1 X5 E1\nG90\nG1 X0')
    expect(ends(p, 0)).toEqual([15, 5, 1])
    expect(p.kinds[0]).toBe(MOVE_EXTRUDE)
    expect(ends(p, 1)).toEqual([20, 5, 1])
    expect(ends(p, 2)).toEqual([0, 5, 1])
  })

  it('G92 moves the origin without drawing', () => {
    const p = parseGcode('G0 X10 Y10\nG92 X0 Y0\nG1 X5')
    expect(p.moveCount).toBe(1)
    expect(seg(p, 0)).toEqual([0, 0, 0, 5, 0, 0])
  })

  it('G20 reads inches and G21 goes back to millimetres', () => {
    const p = parseGcode('G20\nG0 X1 Y0\nG1 X2\nG21\nG1 X60')
    expect(ends(p, 0)[0]).toBeCloseTo(50.8)
    expect(ends(p, 1)[0]).toBe(60)
  })

  it('homing leaves a gap instead of a line from the old position', () => {
    const p = parseGcode('G0 X10 Y10\nG1 X20\nG28\nG0 X30 Y30\nG1 X40')
    expect(p.moveCount).toBe(2)
    expect(seg(p, 1).slice(0, 2)).toEqual([30, 30])
  })

  it('reads compact, lowercase, numbered, signed and CRLF lines', () => {
    const p = parseGcode('N1 G0 X0 Y0\r\ng1 x5 y-2.5\r\nG1X.5Y+1*33\r\n  G1 X7 ; X99\r\n')
    expect(ends(p, 0)).toEqual([5, -2.5, 0])
    expect(ends(p, 1)).toEqual([0.5, 1, 0])
    expect(ends(p, 2)).toEqual([7, 1, 0])
  })
})

describe('what is not a move', () => {
  it('never reads coordinates out of macros, messages or comments', () => {
    const t = ['G0 X0 Y0', 'SET_THING X=99 Y=99', 'CALCULATE_PA X1 Y1', 'M117 X99', 'G1_LIFT X99', 'G38.2 Z-9', '; G1 X99', 'T1', 'G1 X1'].join('\n')
    const p = parseGcode(t)
    expect(p.moveCount).toBe(1)
    expect(ends(p, 0)).toEqual([1, 0, 0])
    expect(p.stats.skipped).toBe(5)
  })

  it('a bare coordinate line is skipped and counted, because Klipper would refuse it', () => {
    const p = parseGcode('G0 X0 Y0\nX10 Y10\nG1 X1')
    expect(ends(p, 0)).toEqual([1, 0, 0])
    expect(p.stats.skipped).toBe(1)
  })
})

describe('arcs', () => {
  const radiusOf = (p: ParsedGcode, i: number, cx: number, cy: number) => {
    const [, , , x, y] = seg(p, i)
    return Math.hypot(x! - cx, y! - cy)
  }

  it('G3 with I J stays on its circle and lands on the end point', () => {
    const p = parseGcode('G0 X10 Y0\nG3 X0 Y10 I-10 J0')
    expect(p.moveCount).toBeGreaterThan(5)
    for (let i = 0; i < p.moveCount; i++) expect(radiusOf(p, i, 0, 0)).toBeCloseTo(10, 3)
    expect(ends(p, p.moveCount - 1)).toEqual([0, 10, 0])
    // anticlockwise from +X to +Y passes through the upper right
    const [, , , mx, my] = seg(p, p.moveCount >> 1)
    expect(mx!).toBeGreaterThan(0)
    expect(my!).toBeGreaterThan(0)
  })

  it('G2 goes the other way round', () => {
    const p = parseGcode('G0 X10 Y0\nG2 X0 Y10 I-10 J0')
    const [, , , mx, my] = seg(p, p.moveCount >> 1)
    expect(mx!).toBeLessThan(0)
    expect(my!).toBeLessThan(0)
    expect(ends(p, p.moveCount - 1)).toEqual([0, 10, 0])
  })

  it('the same start and end point is a full circle', () => {
    const p = parseGcode('G0 X10 Y0\nG2 X10 Y0 I-10 J0')
    const xs = Array.from({ length: p.moveCount }, (_, i) => seg(p, i)[3]!)
    expect(Math.min(...xs)).toBeCloseTo(-10, 0)
  })

  it('reads the R form on the correct side, and negative R the long way', () => {
    const short = parseGcode('G0 X10 Y0\nG3 X0 Y10 R10')
    const long = parseGcode('G0 X10 Y0\nG3 X0 Y10 R-10')
    for (let i = 0; i < short.moveCount; i++) expect(radiusOf(short, i, 0, 0)).toBeCloseTo(10, 3)
    for (let i = 0; i < long.moveCount; i++) expect(radiusOf(long, i, 10, 10)).toBeCloseTo(10, 3)
    expect(long.moveCount).toBeGreaterThan(short.moveCount)
  })

  it('a helix climbs evenly', () => {
    const p = parseGcode('G0 X10 Y0 Z0\nG3 X0 Y10 Z4 I-10 J0')
    expect(ends(p, p.moveCount - 1)[2]).toBe(4)
    expect(seg(p, 0)[5]!).toBeCloseTo(4 / p.moveCount, 4)
  })

  it('every chord of an arc keeps the line it came from', () => {
    const t = 'G0 X10 Y0\nG3 X0 Y10 I-10 J0'
    const p = parseGcode(t)
    for (const o of p.offsets) expect(o).toBe(10)
  })

  it('an arc it can\'t draw is a straight line, counted so the screen can say so', () => {
    const p = parseGcode('G0 X0 Y0\nG18\nG2 X5 Y5 I1 J1\nG17\nG3 X50 Y5 R1')
    expect(p.stats.straightArcs).toBe(2)
    expect(p.moveCount).toBe(2)
  })
})

describe('tool power', () => {
  const LASER = ['G21', 'G90', 'M5', 'G0 X0 Y0', 'M3 S800.000', 'G1 X20 Y0 F600', 'G1 X20 Y10', 'M5', 'G0 X100 Y100', 'G1 X110', 'DEACTIVATE_LASER', 'END_PRINT'].join('\n')

  it('follows M3 and M5 in a Studio laser file', () => {
    const p = parseGcode(LASER)
    expect(p.hasExtrusion).toBe(false)
    expect([...p.power!]).toEqual([800, 800, 0, 0])
  })

  it('takes the bounds from what the tool actually cuts', () => {
    expect(parseGcode(LASER).bounds).toEqual({ min: [0, 0, 0], max: [20, 10, 0] })
  })

  it('ignores S on a move, because Klipper does, and counts it', () => {
    const p = parseGcode('G0 X0 Y0\nM3 S100\nG1 X5 S900\nG1 X6')
    expect([...p.power!]).toEqual([100, 100])
    expect(p.stats.ignoredPower).toBe(1)
  })

  it('M3 with no S keeps the last power, and is still on if none was set', () => {
    expect([...parseGcode('G0 X0 Y0\nM3\nG1 X1').power!]).toEqual([1])
    expect([...parseGcode('G0 X0 Y0\nM4 S50\nM5\nM3\nG1 X1').power!]).toEqual([50])
  })

  it('a G0 with the tool on counts as cutting, because Klipper would move with it on', () => {
    const p = parseGcode('G0 X0 Y0\nM3 S100\nG0 X50 Y50\nM5\nG0 X90 Y90')
    expect(p.kinds[0]).toBe(MOVE_RAPID)
    expect(p.power![0]).toBe(100)
    expect(p.bounds).toEqual({ min: [0, 0, 0], max: [50, 50, 0] })
  })

  it('reads the process from a Studio file, and leaves it unknown otherwise', () => {
    expect(parseGcode('; rhino_process = laser\nG0 X0 Y0').process).toBe('laser')
    expect(parseGcode(ORCA).process).toBeNull()
  })

  it('no M3 anywhere means no power array', () => {
    expect(parseGcode(ORCA).power).toBeNull()
  })

  it('keeps moves from before the first M3 at zero, past an array growth', () => {
    const lines = ['G0 X0 Y0']
    for (let i = 0; i < 70000; i++) lines.push(`G1 X${i % 2}`)
    lines.push('M3 S5')
    for (let i = 0; i < 70000; i++) lines.push(`G1 X${i % 2 ? 0 : 1}`)
    const p = parseGcode(lines.join('\n'))
    expect(p.power![0]).toBe(0)
    expect(p.power![p.moveCount - 1]).toBe(5)
  })
})

describe('layers', () => {
  it('uses slicer markers, with each layer at its printed height', () => {
    const p = parseGcode(ORCA)
    expect(p.layerSource).toBe('markers')
    expect([...p.layerStarts]).toEqual([0, 6])
    expect(p.layerZ[0]).toBeCloseTo(0.2)
    expect(p.layerZ[1]).toBeCloseTo(0.4)
  })

  it('reads Cura\'s marker, and not settings that look like one', () => {
    expect(parseGcode('G0 X0 Y0\n;LAYER:0\nG1 X1 E1').layerSource).toBe('markers')
    expect(parseGcode('G0 X0 Y0 Z0.2\n; layer_height = 0.2\n;LAYER_COUNT:5\nG1 X1 E1').layerSource).toBe('extrusion')
  })

  it('without markers, a Z hop is not a layer', () => {
    const p = parseGcode('M83\nG0 X0 Y0 Z0.2\nG1 X5 E1\nG1 Z0.6\nG1 X9\nG1 Z0.2\nG1 X12 E1\nG1 Z0.4\nG1 X20 E1')
    expect(p.layerSource).toBe('extrusion')
    expect(p.layerStarts.length).toBe(2)
    expect(p.layerZ[1]).toBeCloseTo(0.4)
  })

  it('vase mode doesn\'t make a layer per move', () => {
    const lines = ['M83', 'G0 X0 Y0 Z0.2']
    for (let i = 1; i <= 1000; i++) lines.push(`G1 X${i % 10} Y${i % 7} Z${(0.2 + i * 0.001).toFixed(3)} E1`)
    const p = parseGcode(lines.join('\n'))
    expect(p.layerStarts.length).toBeLessThan(25)
    expect(p.layerStarts.length).toBeGreaterThan(15)
  })

  it('CNC layers are the level cutting depths, not the plunges between them', () => {
    const p = parseGcode(['G21', 'G90', 'G0 X0 Y0 Z5', 'G1 Z-1 F100', 'G1 X10', 'G1 Y10', 'G1 Z-2', 'G1 X0', 'G0 Z5', 'M5'].join('\n'))
    expect(p.layerSource).toBe('depth')
    expect([...p.layerZ]).toEqual([-1, -2])
  })

  it('a flat laser job is one layer, with its passes on the move scrubber', () => {
    const p = parseGcode('G0 X0 Y0\nM3 S5\nG1 X5\nM5\nG0 X0 Y0\nM3 S5\nG1 X5\nM5')
    expect(p.layerStarts.length).toBe(1)
  })

  it('moves that only travel have one layer, and an empty file has none', () => {
    expect(parseGcode('G0 X0 Y0\nG0 X5').layerSource).toBe('none')
    expect(parseGcode('G0 X0 Y0\nG0 X5').layerStarts.length).toBe(1)
    const empty = parseGcode('; nothing\n')
    expect(empty.moveCount).toBe(0)
    expect(empty.layerStarts.length).toBe(0)
    expect(empty.bounds).toBeNull()
  })
})

describe('line width', () => {
  it('follows ;WIDTH: lines, in hundredths of a mm, for printed moves only', () => {
    const p = parseGcode('M83\nG0 X0 Y0\n;WIDTH:0.48\nG1 X1 E1\nG1 X2\n;WIDTH:0.384\nG1 X3 E1\n; WIDTH: 0.5\nG1 X4 E1')
    expect([...p.widths]).toEqual([48, 0, 38, 38])
  })

  it('moves before the first ;WIDTH: have none, and the viewer falls back from there', () => {
    expect([...parseGcode('M83\nG0 X0 Y0\nG1 X1 E1\n;WIDTH:0.4\nG1 X2 E1').widths]).toEqual([0, 40])
  })

  it('ignores a width that makes no sense, and holds a huge one to the top of the scale', () => {
    expect([...parseGcode('M83\nG0 X0 Y0\n;WIDTH:0\nG1 X1 E1\n;WIDTH:-1\nG1 X2 E1\n;WIDTH:9\nG1 X3 E1').widths]).toEqual([0, 0, 255])
  })

  it('reads the nozzle from a slicer file, even at the end, and uses the first of several', () => {
    expect(parseGcode('G0 X0 Y0\nG1 X1\n; nozzle_diameter = 0.6,0.4').nozzle).toBe(0.6)
  })

  it('reads the nozzle from a Studio file\'s settings', () => {
    expect(parseGcode('; rhino_settings = {"nozzle":0.8,"path":0}\nG0 X0 Y0').nozzle).toBe(0.8)
  })

  it('a file that doesn\'t say has no nozzle', () => {
    expect(parseGcode(ORCA).nozzle).toBeNull()
  })
})

describe('file positions and chunks', () => {
  it('each move knows the byte where its line starts, past non-ASCII text', () => {
    const t = '; Größe\nG0 X0 Y0\n  G1 X5\nG1 X6'
    const bytes = new TextEncoder().encode(t)
    const p = parseGcode(bytes)
    const at = (o: number) => new TextDecoder().decode(bytes.subarray(o, o + 5))
    expect(at(p.offsets[0]!)).toBe('  G1 ')
    expect(at(p.offsets[1]!)).toBe('G1 X6')
  })

  it('gives the same answer wherever the chunks fall', () => {
    const bytes = new TextEncoder().encode(`${ORCA}\nG3 X0 Y0 I5 J5\nM3 S10\nG1 X3`)
    const whole = parseGcode(bytes)
    for (let cut = 1; cut < bytes.length; cut++) {
      const p = new GcodeParser()
      p.push(bytes.subarray(0, cut))
      p.push(bytes.subarray(cut))
      expect(p.finish()).toEqual(whole)
    }
  })

  it('gives the same answer one byte at a time, with a line across many chunks', () => {
    const bytes = new TextEncoder().encode(ORCA)
    const p = new GcodeParser()
    for (let i = 0; i < bytes.length; i++) p.push(bytes.subarray(i, i + 1))
    expect(p.finish()).toEqual(parseGcode(bytes))
  })

  it('reads a file with no final newline', () => {
    expect(parseGcode('G0 X0 Y0\nG1 X5').moveCount).toBe(1)
  })

  it('refuses a file too big for its byte offsets', () => {
    const p = new GcodeParser()
    Object.assign(p, { consumed: 2 ** 32 - 1 })
    expect(() => p.push(new Uint8Array(2))).toThrow(/over 4 GB/)
  })
})

describe('big files', () => {
  it('a real-sized file is fine, with no call-stack overflow', () => {
    const lines: string[] = ['G0 X0 Y0 Z0.2']
    for (let i = 0; i < 800_000; i++) lines.push(`G1 X${(i % 500) + 0.5} Y${i % 300} E0.01`)
    const p = parseGcode(lines.join('\n'))
    expect(p.moveCount).toBe(800_000)
    expect(p.segments.length).toBe(4_800_000)
    expect(p.offsets[799_999]).toBeGreaterThan(p.offsets[0]!)
  })

  it('results are exact-size arrays with their own buffers, safe to transfer', () => {
    const p = parseGcode(ORCA)
    expect(p.segments.buffer.byteLength).toBe(p.moveCount * 24)
    expect(new Set(transferables(p)).size).toBe(transferables(p).length)
  })
})

describe('reading from the machine', () => {
  const streamOf = (text: string, size = 7) => {
    const bytes = new TextEncoder().encode(text)
    return new ReadableStream<Uint8Array>({
      start(c) {
        for (let i = 0; i < bytes.length; i += size) c.enqueue(bytes.subarray(i, i + size))
        c.close()
      },
    })
  }
  const url = 'http://rhino/server/files/gcodes/a.gcode'

  it('accepts only files in the gcodes folder', () => {
    expect(isGcodeFileUrl(url)).toBe(true)
    expect(isGcodeFileUrl('/server/files/gcodes/parts/a.gcode')).toBe(true)
    expect(isGcodeFileUrl('http://rhino/server/files/config/printer.cfg')).toBe(false)
    expect(isGcodeFileUrl('http://rhino/printer/gcode/script?script=G28')).toBe(false)
    expect(isGcodeFileUrl('file:///server/files/gcodes/a')).toBe(false)
    expect(isGcodeFileUrl('javascript:alert(1)')).toBe(false)
  })

  it('refuses any other address without fetching it', async () => {
    const f = vi.fn()
    vi.stubGlobal('fetch', f)
    await expect(runParse({ url: 'http://rhino/server/files/config/printer.cfg' }, () => {})).rejects.toThrow(/G-code folder/)
    expect(f).not.toHaveBeenCalled()
    vi.unstubAllGlobals()
  })

  it('streams a file, reads it with a plain GET, and reports the size', async () => {
    const f = vi.fn(async () => new Response(streamOf(ORCA), { headers: { 'content-length': String(ORCA.length) } }))
    vi.stubGlobal('fetch', f)
    const seen: Array<[number, number | null]> = []
    const p = await runParse({ url }, (d, t) => seen.push([d, t]))
    vi.unstubAllGlobals()
    expect(p).toEqual(parseGcode(ORCA))
    expect(seen.at(-1)).toEqual([ORCA.length, ORCA.length])
    const init = (f.mock.calls[0] as unknown[])[1] as RequestInit
    expect(init.method).toBeUndefined()
    expect(init.body).toBeUndefined()
  })

  it('stops before reading a file over the size it was given', async () => {
    vi.stubGlobal('fetch', async () => new Response(streamOf(ORCA), { headers: { 'content-length': String(ORCA.length) } }))
    const e = await runParse({ url, maxBytes: ORCA.length - 1 }, () => {}).catch((x: unknown) => x)
    expect(e).toBeInstanceOf(FileTooBig)
    expect((e as FileTooBig).bytes).toBe(ORCA.length)
    expect((await runParse({ url, maxBytes: ORCA.length }, () => {})).moveCount).toBeGreaterThan(0)
    vi.unstubAllGlobals()
  })

  it('says so when the machine refuses', async () => {
    vi.stubGlobal('fetch', async () => new Response('', { status: 404 }))
    await expect(runParse({ url }, () => {})).rejects.toThrow(/HTTP 404/)
    vi.unstubAllGlobals()
  })

  it('reads text it already has without fetching', async () => {
    const f = vi.fn()
    vi.stubGlobal('fetch', f)
    expect((await runParse({ text: ORCA }, () => {})).moveCount).toBe(8)
    expect(f).not.toHaveBeenCalled()
    vi.unstubAllGlobals()
  })
})

describe('look-only', () => {
  it('nothing in this folder can reach the machine\'s controls', () => {
    const banned = /moonraker\/|stores\/|control\/|portal\/|runScript|WebSocket|method:\s*['"](POST|PUT|DELETE)/
    for (const dir of [__dirname, join(__dirname, '..', 'viewer')]) {
      const files = readdirSync(dir).filter((f) => !f.endsWith('.test.ts'))
      expect(files.length).toBeGreaterThan(0)
      for (const f of files) expect(readFileSync(join(dir, f), 'utf8'), f).not.toMatch(banned)
    }
  })
})
